import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Route, Router } from '@angular/router';
import { min } from 'rxjs';
import { AuthService } from 'src/app/service/auth.service';
import { jobSeeker } from '../../Models/jobSeeker';

@Component({
  selector: 'app-seeker',
  templateUrl: './seeker.component.html',
  styleUrls: ['./seeker.component.css']
})
export class SeekerComponent {

  constructor(private route : Router,private service  : AuthService, private fb : FormBuilder){}


regSeeker = this.fb.group({
  firstName : ['', Validators.required],
  lastName : ['',Validators.required],
  email : ['',[Validators.required,Validators.email]],
  password : ['',[Validators.required, Validators.minLength(6)]],
   skills:  ['', Validators.required],
  location : ['',Validators.required]
});


 onSubmit() {

  if (this.regSeeker.invalid) {
    alert("Please fill all required fields.");
    return;
  }

  const formValue: jobSeeker = {
    firstName: this.regSeeker.value.firstName!,
    lastName: this.regSeeker.value.lastName!,
    email: this.regSeeker.value.email!,
    password: this.regSeeker.value.password!,
    location: this.regSeeker.value.location!,
    skills: this.regSeeker.value.skills!
      .split(',')
      .map(skill => skill.trim())
      .filter(skill => skill !== '')
  };

  this.service.signUp(formValue).subscribe({
    next: (res) => {
      console.log(res);

      alert("Profile Created Successfully");

      this.regSeeker.reset();

      this.route.navigate(['/auth/login']);
    },

    error: (err) => {
      console.error(err);
      alert("Registration Failed");
    }
  });
}


}
<div class="page">
<app-header variant="guest"></app-header>

<div class="auth-wrap">
  <form [formGroup]="regSeeker" (ngSubmit)="onSubmit()">
    <div class="auth-card">
      <h2>Create your Job Seeker account</h2>
      <div class="card-row">
        <div class="field"><label>First name</label><input formControlName="firstName" placeholder="Aditi"></div>
        <div class="field"><label>Last name</label><input formControlName="lastName" placeholder="Menon"></div>
      </div>
      <div class="field"><label>Email</label><input formControlName="email" type="email" placeholder="aditi@email.com"></div>
      <div class="field"><label>Password</label><input formControlName="password" type="password" placeholder="&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;"></div>
      <div class="field"><label>Location</label><input formControlName="location" placeholder="Kochi, IN"></div>
      <div class="field"><label>Primary skills</label><input formControlName="skills" placeholder="Java, React"></div>
      <button class="btn btn-primary btn-block" type="submit">Create account</button>
    </div>
  </form>
</div>

<app-footer></app-footer>
</div>
